import {ensureUnlock} from '@app/web-player/chat/notification-sound';
import {useChatWidget} from '@app/web-player/chat/chat-widget';
import {useAuth} from '@common/auth/use-auth';
import {Navbar} from '@common/ui/navigation/navbar/navbar';
import {IconButton} from '@ui/buttons/icon-button';
import {Badge} from '@ui/badge/badge';
import {ChatIcon} from '@ui/icons/material/Chat';

export function MobileNavbar() {
  const {isLoggedIn, hasPermission, user} = useAuth();
  const chatWidget = useChatWidget();
  const showChatButton = isLoggedIn && user && hasPermission('chat.view');

  return (
    <Navbar
      color="bg-elevated"
      darkModeColor="bg-elevated"
      logoColor="matchMode"
      border="border-b"
      textColor="text-main"
      size={null}
      className="flex-shrink-0 px-2 py-8"
      rightChildren={
        showChatButton ? (
          <IconButton
            onClick={(e) => {
              e.preventDefault();
              e.stopPropagation();
              ensureUnlock();
              try {
                if (chatWidget) {
                  chatWidget.setIsOpen(true);
                }
              } catch (error) {
              }
            }}
            size="sm"
            aria-label="Open chat"
            badge={
              chatWidget && chatWidget.unreadCount > 0 ? (
                <Badge 
                  color="bg-danger text-white" 
                  className="min-w-[18px] h-[18px] flex items-center justify-center px-1 text-[10px] font-bold rounded-full"
                >
                  {chatWidget.unreadCount > 99 ? '99+' : chatWidget.unreadCount}
                </Badge>
              ) : undefined
            }
          >
            <ChatIcon />
          </IconButton>
        ) : undefined
      }
    />
  );
}
